private void forVarDeclPrePass(VarDecl v) {
    List<LValue> lhs = v.getLhs();
    Option<Expr> oinit = v.getInit();
    if (lhs.size() != 1) {
        throw sayWhat(v,"VarDecl "+v+" tupled lhs not handled.");
    }
    if (!oinit.isSome()) {
        debug("VarDecl ", v, " skipping abs var decl.");
        return;
    }
    LValue lv = lhs.get(0);
    Id var = lv.getName();
    Type ty = (Type)lv.getIdType().unwrap();
    Expr exp = oinit.unwrap();
    boolean isMutable = lv.isMutable();
    String classFile = NamingCzar.jvmClassForToplevelDecl(var, packageAndClassName);
    String tyName = NamingCzar.jvmBoxedTypeName(ty, thisApi());
    debug("VarDeclPrePass ", var, " : ", ty, " = ", exp);
    new CodeGen(this).generateVarDeclInnerClass(v, classFile, tyName, exp, isMutable);
}

/** The binding for a top-level variable, registered for the whole component
 *  before any initializer is generated.  Declarations that
 *  forVarDeclPrePass does not generate a class for are skipped here and
 *  rejected there. */
private void addTopLevelVarBinding(VarDecl v) {
    List<LValue> lhs = v.getLhs();
    if (lhs.size() != 1 || !v.getInit().isSome()) {
        return;
    }
    LValue lv = lhs.get(0);
    Id var = lv.getName();
    Type ty = (Type)lv.getIdType().unwrap();
    String classFile = NamingCzar.jvmClassForToplevelDecl(var, packageAndClassName);
    String tyName = NamingCzar.jvmBoxedTypeName(ty, thisApi());
    addStaticVar(
        lv.isMutable()
            ? new VarCodeGen.MutableStaticBinding(var, ty, classFile,
                                                  NamingCzar.SINGLETON_FIELD_NAME, tyName)
            : new VarCodeGen.StaticBinding(var, ty, classFile,
                                           NamingCzar.SINGLETON_FIELD_NAME,
                                           Naming.internalToDesc(tyName)));
}

/** Whether an imported top-level variable is declared mutable by the api
 *  that declares it.  A mutable variable's singleton field holds a
 *  MutableFValue cell rather than the value (generateVarDeclInnerClass),
 *  so a reference to it needs the matching binding -- the same
 *  distinction addTopLevelVarBinding makes for a variable this component
 *  declares itself. */
private boolean importedVarIsMutable(Id id) {
    Option<APIName> oapi = id.getApiName();
    if (!oapi.isSome()) return false;
    ApiIndex ai = env.apis().get(oapi.unwrap());
    if (ai == null) return false;
    Variable var = ai.variables().get(NodeFactory.makeLocalId(id));
    return var != null && var.mutable();
}

